public int snakesAndLadders(int[][] board) {
    int n = board.length;
    boolean[] visited = new boolean[n * n + 1];
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(1);
    visited[1] = true;
    int moves = 0;
    while (!queue.isEmpty()) {
        int size = queue.size();
        for (int i = 0; i < size; i++) {
            int label = queue.poll();
            if (label == n * n) {
                return moves;
            }
            for (int next = label + 1; next <= Math.min(label + 6, n * n); next++) {
                int[] rc = toCoord(next, n);
                int dest = board[rc[0]][rc[1]];
                int target = (dest == -1) ? next : dest; // forced jump, once
                if (!visited[target]) {
                    visited[target] = true; // mark on enqueue
                    queue.offer(target);
                }
            }
        }
        moves++;
    }
    return -1;
}

private int[] toCoord(int label, int n) {
    int quotient = (label - 1) / n;
    int remainder = (label - 1) % n;
    int row = n - 1 - quotient; // numbering starts at the bottom
    int col = (quotient % 2 == 0) ? remainder : n - 1 - remainder;
    return new int[]{row, col};
}

