public int snakesAndLadders(int[][] board) {
    int n = board.length;
    int[] dist = new int[n * n + 1];
    Arrays.fill(dist, -1);
    dist[1] = 0;
    Queue<Integer> queue = new LinkedList<>();
    queue.offer(1);
    while (!queue.isEmpty()) {
        int label = queue.poll();
        if (label == n * n) {
            return dist[label];
        }
        for (int next = label + 1; next <= Math.min(label + 6, n * n); next++) {
            int[] rc = toCoord(next, n);
            int dest = board[rc[0]][rc[1]];
            int target = (dest == -1) ? next : dest;
            if (dist[target] == -1) {
                dist[target] = dist[label] + 1;
                queue.offer(target);
            }
        }
    }
    return dist[n * n];
}

private int[] toCoord(int label, int n) {
    int quotient = (label - 1) / n;
    int remainder = (label - 1) % n;
    int row = n - 1 - quotient;
    int col = (quotient % 2 == 0) ? remainder : n - 1 - remainder;
    return new int[]{row, col};
}

